import{_ as e,o,c as d,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Contracts 1.1.0 — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contracts 1.1.0 — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/contracts-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contracts 1.1.0 — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/contracts-production-readiness"}]]},"headers":[],"relativePath":"deployment/contracts-production-readiness.md","filePath":"deployment/contracts-production-readiness.md","lastUpdated":1788201759000}'),a={name:"deployment/contracts-production-readiness.md"};function n(s,t,i,c,l,g){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="contracts-1-1-0-—-production-readiness-audit" tabindex="-1">Contracts 1.1.0 — Production Readiness Audit <a class="header-anchor" href="#contracts-1-1-0-—-production-readiness-audit" aria-label="Permalink to &quot;Contracts 1.1.0 — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-08-18</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — Backend migrate before SPA</td></tr><tr><td><strong>Scope</strong></td><td>Tenant Contracts module <code>contracts</code> <strong>1.0.0 → 1.1.0</strong> (opportunity auto-fill + HTML description/notes)</td></tr><tr><td><strong>Branch</strong></td><td><code>feature/billing-documents-discounts-and-terms</code></td></tr><tr><td><strong>Companion</strong></td><td><a href="./contracts">Contracts production</a> · <a href="/developer-guide/contracts">Developer</a> · <a href="/user-guide/contracts">User</a> · <a href="/api/tenant-v1-contracts">API</a></td></tr></tbody></table><p>Additive MINOR on the existing contracts module. No new permissions, queues, scheduler entries, or env vars. Catalog bump does <strong>not</strong> auto-install for workspaces that never entitled Contracts.</p><p>This audit is <strong>Contracts 1.1.0 only</strong>. Billing document product-picker on the same branch is a separate <a href="./billing-product-line-picker-production-readiness">Go</a>.</p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Selecting an <strong>Opportunity</strong> on create auto-fills title (when empty), party name (contact or company), value, currency, and an <strong>eligible</strong> assignee. A linked quotation is auto-selected only when that opportunity has exactly one quotation. New <code>description</code> plus existing <code>notes</code> are TipTap HTML, sanitized on save (<code>DocumentHtmlSanitizer</code>) and display (<code>sanitizeDocumentHtml</code>). Timeline comments stay plain text.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td><code>module:contracts</code> + <code>contracts.*</code> (no new family)</td><td><strong>Pass</strong></td></tr><tr><td>Tenant isolation + assignee scope</td><td><strong>Pass</strong></td></tr><tr><td><code>LinkableQuotation</code> entitlement / same opportunity</td><td><strong>Pass</strong></td></tr><tr><td>HTML sanitizer on save + DOMPurify on Overview</td><td><strong>Pass</strong></td></tr><tr><td>Timeline comments remain plain text</td><td><strong>Pass</strong></td></tr><tr><td>End date on or after start (API + SPA)</td><td><strong>Pass</strong> (F2)</td></tr><tr><td>Owner create from opportunity</td><td><strong>Pass</strong> (F1 + F5)</td></tr><tr><td>Eligible picker matches payload</td><td><strong>Pass</strong> (F5)</td></tr><tr><td>Catalog <code>1.1.0</code> migrate-only</td><td><strong>Pass</strong></td></tr><tr><td>Pest HTML + owner self-assign + end date</td><td><strong>Pass</strong></td></tr><tr><td>Playwright one-session contracts + sales</td><td><strong>Pass</strong> (F4)</td></tr><tr><td>Docs + upgrade + this page</td><td><strong>Pass</strong> (F3)</td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> after companion CI and <code>php artisan migrate --force</code> <strong>before</strong> the SPA that posts <code>description</code>.</p><hr><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Action</th></tr></thead><tbody><tr><td>F1</td><td>High</td><td><strong>Fixed</strong></td><td>Opportunity auto-fill copied <code>assigned_to</code> from the deal (workspace owner). <code>EligibleOpportunityAssignee</code> 422ed</td><td><code>StoreContractRequest</code> allows the creating actor; Pest owner self-assign</td></tr><tr><td>F2</td><td>Medium</td><td><strong>Fixed</strong></td><td>End date before start had no SPA error; no Pest for <code>after_or_equal</code></td><td>Zod <code>.superRefine</code> + <code>errors.end_date</code>; Pest <code>rejects an end date before the start date</code></td></tr><tr><td>F3</td><td>Low</td><td><strong>Fixed</strong></td><td>No upgrade runbook / dedicated readiness page</td><td>This page + <a href="/deployment/upgrade">Upgrade</a></td></tr><tr><td>F4</td><td>Low</td><td><strong>Fixed</strong></td><td>Sales shared-session e2e blocked by driver.js overlay; 180s timeout</td><td><code>suppressModuleTourAutoStart</code> + <code>test.setTimeout(300_000)</code></td></tr><tr><td>F5</td><td>Medium</td><td><strong>Fixed</strong></td><td>Picker listed all users / auto-fill hid owner id behind Unassigned</td><td><code>filterLeadAssigneeOptions</code> on form + detail; copy assignee only when listed</td></tr></tbody></table><h3 id="accepted-intentional" tabindex="-1">Accepted / intentional <a class="header-anchor" href="#accepted-intentional" aria-label="Permalink to &quot;Accepted / intentional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td>No new permissions</td><td>Reuse <code>contracts.create</code> / <code>update</code> / <code>view</code></td></tr><tr><td>Owner as assignee</td><td>Owners stay ineligible in the picker. Create with omitted <code>assigned_to</code> still defaults to the actor in <code>ContractService</code>. API may pass <code>assigned_to</code> = actor (F1).</td></tr><tr><td>Timeline comments</td><td><code>contract_notes.body</code> remains plain text</td></tr><tr><td>Catalog bump ≠ auto-install</td><td>Workspaces that never entitled Contracts are unchanged</td></tr><tr><td>Same-branch billing picker</td><td>Do not mix catalog versions with quotations/estimates/invoices product_id</td></tr></tbody></table><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>php artisan test --compact tests/Feature/Tenant/Contract/ContractTest.php</code></td><td>Required green (23 cases: HTML, owner self-assign, end date)</td><td>Isolation, quotation entitlement, status machine, assignee scope, audit unchanged</td></tr><tr><td><code>npm run test:e2e:contracts</code></td><td><strong>1 passed (~1.6m)</strong></td><td>One login: empty-form validation, auto-fill, end-date mistake, TipTap, search, Overview HTML, Notes tab, activate, terminate, timeline</td></tr><tr><td><code>npm run test:e2e:sales</code></td><td><strong>4 passed (~3.0m)</strong></td><td>Shared session: opportunities → pipeline → quotations send/accept → contracts HTML create/activate/terminate</td></tr></tbody></table><p><strong>Contracts e2e (single session):</strong> empty submit → Opportunity/Title/Start date required; pick opportunity → title, party, EUR, value, quotation; end date before start → client error; TipTap description + notes; create; search; Overview HTML; Notes tab comment; Activate; Terminate; Timeline created.</p><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li>Companion <strong>CI</strong> green (Backend / Frontend / Docs)</li><li><strong>Backend</strong> — <code>php artisan migrate --force</code> (<code>add_description_to_contracts_table</code> + catalog bump <code>1.1.0</code>)</li><li>Confirm catalog <code>contracts</code> version <code>1.1.0</code> (no <code>db:seed</code>)</li><li><strong>SPA</strong> — opportunity auto-fill + TipTap description/notes + eligible assignee picker</li><li><strong>Docs</strong></li><li>Staging smoke below before production traffic</li></ol><p>Suggested merge: <strong>Backend → Frontend → Docs</strong>. Do <strong>not</strong> <code>db:seed</code>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Pest <code>ContractTest</code> green in CI (HTML, owner self-assign, end date)</td><td>Eng</td><td>☐</td></tr><tr><td>2</td><td>Playwright <code>test:e2e:contracts</code> (+ sales if in the same PR)</td><td>QA</td><td>☐</td></tr><tr><td>3</td><td>Migrations applied (<code>description</code> column + bump <code>1.1.0</code>)</td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Catalog <code>contracts</code> version <code>1.1.0</code></td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>SPA deployed <strong>after</strong> migrate</td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Staging smoke signed off</td><td>QA / Ops</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace → Opportunities, then Contracts (free). Optionally Quotations.</li><li>New contract → empty <strong>Create</strong> shows Opportunity / Title / Start date required</li><li>Pick an opportunity that has a contact, amount, currency, and (if entitled) exactly one quotation → party, value, currency, title, quotation fill. Assignee stays <strong>Unassigned</strong> when the deal is owned by the workspace owner (then save assigns the actor).</li><li>Set end date <strong>before</strong> start → error; fix end date</li><li>Description + Notes rich text → save → Overview shows sanitized HTML (bold/lists; no script)</li><li>Notes tab: add a <strong>plain</strong> comment</li><li>Activate → Terminate</li><li>Soft-delete → Deleted only → Restore (owner)</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA (auto-fill/TipTap disappear; <code>description</code> column remains)</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive migrations</td></tr><tr><td>Module disable</td><td>Marketplace uninstall (contract rows retained)</td></tr><tr><td>Schema</td><td>Do <strong>not</strong> drop <code>description</code> in prod without a data plan</td></tr><tr><td>Catalog</td><td>Bump-down is not required; display version can stay <code>1.1.0</code></td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit: <code>contract_created</code>, <code>contract_updated</code>, <code>contract_deleted</code>, <code>contract_assigned</code>, <code>contract_status_changed</code>, <code>contract_note_added</code></li><li>Nightwatch: <code>POST /api/tenant/v1/contracts</code> 422 rate after SPA rollout (assignee / end_date)</li><li>Spatie log name <code>contracts</code></li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Engineering</td><td></td><td></td><td><strong>Go</strong> / No-Go</td></tr><tr><td>Product</td><td></td><td></td><td>F1–F5 fixed</td></tr><tr><td>Ops</td><td></td><td></td><td>Staging migrate + smoke ☐</td></tr></tbody></table><p><strong>Recommendation:</strong> Merge after CI; migrate-first on staging, then production.</p>',38)])])}const u=e(a,[["render",n]]);export{h as __pageData,u as default};
